/** Create the built-in Apps that are missing. Quiet: this runs for everyone on every load. */
export async function ensureDefaultApp(store: Store): Promise<void> {
  if (!appsPlusAvailable(store)) {
    return;
  }

  const apps = await store.dispatch('management/findAll', { type: APP }).catch(() => null);

  if (!apps) {
    return;
  }

  const byName = new Map(apps.map((app: Json) => [app.metadata?.name, app]));

  for (const body of [rancherWorkspaceApp(), dashboardPreviewApp(), devBrowserApp()]) {
    // The definition's fingerprint rides on the App, so a definition that changed in this bundle
    // reaches a cluster that already has the App - the templates lesson: an App seeded once and
    // never touched again strands every workspace made after the definition moved on. Existing
    // Installations keep what they rendered; new ones get the new templates.
    const fingerprint = definitionVersion(body.spec);
    const existing: Json = byName.get(body.metadata.name);
    // Two dashboards on different versions of this extension must not take turns rewriting the
    // App - Apps Plus re-renders every Installation each time, replacing running workspace
    // pods mid-conversation. Versions up to 0.3.2 compare the older annotation with their own
    // fingerprint and rewrite on a mismatch, so it is left holding the value they expect
    // (LEGACY_FINGERPRINTS) and this version keeps its own in an annotation of its own.
    const annotations = {
      ...(body.metadata.annotations || {}),
      [DEFINITION_ANNOTATION]:    LEGACY_FINGERPRINTS[body.metadata.name] || fingerprint,
      [DEFINITION_ANNOTATION_V2]: LEGACY_FINGERPRINTS_V2[body.metadata.name] || fingerprint,
      [DEFINITION_ANNOTATION_V3]: LEGACY_FINGERPRINTS_V3[body.metadata.name] || fingerprint,
      [DEFINITION_ANNOTATION_V4]: LEGACY_FINGERPRINTS_V4[body.metadata.name] || fingerprint,
      [DEFINITION_STAMP]:         `${ extensionVersion() }|${ fingerprint }`,
    };

    body.metadata.annotations = annotations;

    if (!existing) {
      const app = await store.dispatch('management/create', { type: APP, ...body });

      await app.save().catch(() => {});
    } else if (shouldRewrite(existing.metadata?.annotations?.[DEFINITION_STAMP], fingerprint)) {
      existing.spec = body.spec;
      existing.metadata.annotations = { ...(existing.metadata.annotations || {}), ...annotations };
      await existing.save().catch(() => {});
    }
  }
}

/** Where an App carries the fingerprint of the definition that wrote it. */
export const DEFINITION_ANNOTATION_V2 = 'dev.rancher.io/definition-v2';
/** The annotation versions up to 0.3.2 read; see ensureDefaultApp for why it is kept. */
export const DEFINITION_ANNOTATION = 'dev.rancher.io/definition';
/** What a 0.3.2 dashboard computes for the Apps it knows, so it finds them as it left them. */
const LEGACY_FINGERPRINTS: Record<string, string> = { [DEFAULT_APP]: '50f2859d', [BROWSER_APP]: 'fff28dbc' };
/** Where this version keeps its fingerprint; 0.3.3 to 0.3.10 read the -v2 one the same way 0.3.2 read the first. */
export const DEFINITION_ANNOTATION_V3 = 'dev.rancher.io/definition-v3';
/** What a 0.3.10 dashboard computes for the Apps it knows, kept in -v2 so it leaves them be. */
const LEGACY_FINGERPRINTS_V2: Record<string, string> = {
  'rancher-dev': 'aac0f653', 'dashboard-preview': 'ee04e302', 'dev-browser': 'fff28dbc',
};
/** Where this version keeps its fingerprint; 0.3.11 to 0.3.15 read -v3. */
export const DEFINITION_ANNOTATION_V4 = 'dev.rancher.io/definition-v4';
/** What a 0.3.15 dashboard computes, kept in -v3 so it leaves the Apps be. */
const LEGACY_FINGERPRINTS_V3: Record<string, string> = {
  'rancher-dev': '997b8aae', 'dashboard-preview': 'ee04e302', 'dev-browser': 'fff28dbc',
};
/** What a 0.3.19 dashboard computes, kept in -v4 so it leaves the Apps be. The last of these. */
const LEGACY_FINGERPRINTS_V4: Record<string, string> = {
  'rancher-dev': '997b8aae', 'dashboard-preview': '15f54d51', 'dev-browser': 'fff28dbc',
};

/**
 * Where the fingerprint lives from 0.3.20 on, and the end of the pacifier ladder above.
 *
 * Four versions of this extension have each added an annotation of their own, because an older
 * tab that finds a fingerprint it did not write rewrites the App back to the definition it
 * knows, and two tabs then take turns replacing every workspace's pods. What stops that for
 * good is saying *who* wrote it: this annotation carries the extension's version beside the
 * fingerprint, and a dashboard older than the one that wrote it leaves the App alone. An
 * older tab is then wrong about the App for as long as it stays open, which is what it should
 * be - it is the one that is behind.
 */
export const DEFINITION_STAMP = 'dev.rancher.io/definition-by';

function extensionVersion(): string {
  try {
    // eslint-disable-next-line @typescript-eslint/no-var-requires, global-require
    return String(require('./package.json').version || '0.0.0');
  } catch {
    return '0.0.0';
  }
}

/** `a` is older than `b`, by the numbers in them. */
function olderThan(a: string, b: string): boolean {
  const left = a.split('.').map((part) => parseInt(part, 10) || 0);
  const right = b.split('.').map((part) => parseInt(part, 10) || 0);

  for (let i = 0; i < Math.max(left.length, right.length); i++) {
    if ((left[i] || 0) !== (right[i] || 0)) {
      return (left[i] || 0) < (right[i] || 0);
    }
  }

  return false;
}

/** Rewrite when the definition moved on, unless a newer dashboard wrote what is there. */
function shouldRewrite(stamp: string | undefined, fingerprint: string): boolean {
  const [wroteVersion = '0.0.0', wroteFingerprint = ''] = String(stamp || '').split('|');

  if (wroteFingerprint === fingerprint) {
    return false;
  }

  return !olderThan(extensionVersion(), wroteVersion);
}

function definitionVersion(spec: Json): string {
  const text = JSON.stringify(spec);
  let h = 2166136261;

  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }

  return (h >>> 0).toString(16);
}
